using System;using System.IO;using System.Text;using System.Text.Json;using System.Collections.Generic;using System.Linq;
public class DeepAudit{
byte[] b; long root; public DeepAudit(byte[] bytes,long r=0){b=bytes;root=r;} int I(long p)=>checked((int)(root+p));uint U(long p)=>BitConverter.ToUInt32(b,I(p));ushort H(long p)=>BitConverter.ToUInt16(b,I(p));long L(long p)=>BitConverter.ToInt64(b,I(p));float F(long p)=>BitConverter.ToSingle(b,I(p));byte B(long p)=>b[I(p)];string W(long p){if(p==0)return "";int s=I(p),e=s;while(e+1<b.Length&&(b[e]!=0||b[e+1]!=0))e+=2;return Encoding.Unicode.GetString(b,s,e-s);} 
public static Dictionary<uint,string> BoneNames=new();
public static object Parse(string file){var a=new DeepAudit(File.ReadAllBytes(file));uint magic=a.U(4);if(magic==0x74736c6d||magic==0x6b63706d)return a.List(magic==0x6b63706d);if(file.Contains(".jmap."))return a.Mask();if(file.Contains(".motfsm2."))return a.Fsm();throw new Exception("unknown");}
object List(bool pack){int n=(int)U(pack?32:56);long ptr=L(16),idx=L(24);var rows=new List<object>();for(int i=0;i<n;i++){long off=L(ptr+i*8);object payload=null;if(off>0){var a=new DeepAudit(b,root+off);if(a.U(4)==0x20746f6d)payload=a.Mot();else if(a.U(4)==0x6572746d)payload=a.Tree();}rows.Add(new{Slot=i,ID=pack?U(idx+i*4):H(idx+i*72+8),Switch=pack?0:H(idx+i*72+10),Offset=off,PackIndex=pack?i:unchecked((int)U(idx+i*72+68)),Type=pack?1:B(idx+i*72+20),ReferenceSelector=pack?0:B(idx+i*72+67),Payload=payload});}return new{Kind=pack?"motpack":"motlist",Name=pack?"":W(L(32)),Rows=rows};}
object Mot(){long bone=L(16);if(bone>0 && root+bone+16<b.Length && (U(12)==0||bone<U(12))){long n=L(bone+8);if(n>0&&n<5000){for(int i=0;i<n;i++){long p=bone+16+i*80;BoneNames[U(p+68)]=W(L(p));}}}
var tracks=new List<object>();long t=L(24);for(int i=0;i<H(114);i++){long p=t+i*12;tracks.Add(new{Hash=U(p+4),Index=H(p),Flags=B(p+2),Weight=B(p+3)/255.0});}return new{Kind="mot",Name=W(L(88)),Frames=F(96),FPS=H(120),BoneCount=H(112),Tracks=tracks,Jmap=L(56)>0?W(L(56)):"",ClipCount=B(116),ClipOffset=L(48)};}
object Tree(){long np=L(32),lp=L(40);var nodes=new List<object>();for(int i=0;i<H(72);i++){long p=np+i*48,dp=L(p+24);var pars=new List<object>();for(int j=0;j<B(p+45);j++){long q=dp+j*16;uint ty=U(q);long v=L(q+8);object val=v;if(ty==9)val=F(q+8);else if(ty==12)val=W(v);else if(ty==0)val=v!=0;else if(ty==13)val="buffer:"+U(q+4);pars.Add(new{Type=ty,Hash=U(q+4),Value=val});}nodes.Add(new{Index=i,Name=W(L(p)),TypeHash=U(p+32),SubTypeHash=U(p+36),Parameters=pars});}var links=new List<object>();for(int i=0;i<H(74);i++){long p=lp+i*40;links.Add(new{Input=U(p),InputPin=U(p+4),Output=U(p+8),OutputPin=U(p+12),Type=U(p+16)});}return new{Kind="tree",Name=W(L(48)),Nodes=nodes,Links=links};}
object Mask(){if(U(0)!=28)throw new Exception("jmap version");long p=L(16);var groups=new List<object>();for(int i=0;i<H(116);i++){long q=p+i*32;var joints=new List<object>();for(int j=0;j<H(q+28);j++){uint hash=U(L(q)+j*4);joints.Add(new{Hash=hash,Name=BoneNames.GetValueOrDefault(hash,"?"),Mask=L(q+8)>0?B(L(q+8)+j):0,Weight=L(q+16)>0?F(L(q+16)+j*4):0});}groups.Add(new{ID=U(q+24),Joints=joints});}return new{Kind="jmap",Version=U(0),Groups=groups};}
object Graph(){long node=L(12),str=L(108);using var r=new BinaryReader(new MemoryStream(b));r.BaseStream.Position=root+node;int n=r.ReadInt32();if(n<0||n>100000)throw new Exception("bad node count "+n);var nodes=new List<object>();var edges=new List<object>();
uint[][] Matrix(int cols){int count=r.ReadInt32();if(count<0||count>100000)throw new Exception("bad count "+count);var a=new uint[cols][];for(int c=0;c<cols;c++){a[c]=new uint[count];for(int i=0;i<count;i++)a[c][i]=r.ReadUInt32();}return a;}
uint[][] EventsMatrix(int cols){int count=r.ReadInt32();if(count<0||count>100000)throw new Exception("bad event count "+count);for(int i=0;i<count;i++){int ec=r.ReadInt32();r.BaseStream.Position+=ec*4;}var a=new uint[cols][];for(int c=0;c<cols;c++){a[c]=new uint[count];for(int i=0;i<count;i++)a[c][i]=r.ReadUInt32();}return a;}
for(int i=0;i<n;i++){long at=r.BaseStream.Position;uint id=r.ReadUInt32(),ex=r.ReadUInt32();int name=r.ReadInt32();uint parent=r.ReadUInt32(),pex=r.ReadUInt32();var children=Matrix(3);int selector=r.ReadInt32();int callers=r.ReadInt32();r.BaseStream.Position+=callers*4;uint callerCond=r.ReadUInt32();var actions=Matrix(2);int priority=r.ReadInt32();ushort attr=r.ReadUInt16();r.ReadUInt16();if((attr&32)!=0){r.ReadUInt32();r.ReadUInt32();int tc=r.ReadInt32();r.BaseStream.Position+=tc*4;r.ReadBoolean();r.ReadBoolean();}var states=EventsMatrix(5);var starts=EventsMatrix(3);var all=(attr&4)==0?Matrix(5):new uint[][]{Array.Empty<uint>(),Array.Empty<uint>(),Array.Empty<uint>(),Array.Empty<uint>(),Array.Empty<uint>()};int refTree=r.ReadInt32();nodes.Add(new{Index=i,ID=id,Ex=ex,Name=W(str+4+name*2),Parent=parent,ParentEx=pex,Actions=actions,Selector=selector,Offset=at-root,Attributes=attr});for(int k=0;k<children[0].Length;k++)edges.Add(new{Kind="child",From=id,FromEx=ex,To=children[0][k],ToEx=children[1][k],Condition=children[2][k],Transition=0u});for(int k=0;k<states[0].Length;k++)edges.Add(new{Kind="state",From=id,FromEx=ex,To=states[0][k],ToEx=states[3][k],Condition=states[1][k],Transition=states[2][k]});for(int k=0;k<all[0].Length;k++)edges.Add(new{Kind="anyState",From=id,FromEx=ex,To=all[0][k],ToEx=all[3][k],Condition=all[1][k],Transition=all[2][k]});for(int k=0;k<starts[0].Length;k++)edges.Add(new{Kind="start",From=id,FromEx=ex,To=starts[0][k],ToEx=starts[2][k],Condition=starts[1][k],Transition=0u});}return new{Nodes=nodes,Edges=edges,EndOffset=r.BaseStream.Position-root,ActionRszOffset=L(20),ConditionRszOffset=L(44)};}

object Fsm(){long t=L(32),mp=L(24);var transitions=new List<object>();for(int i=0;i<U(60);i++){long p=t+i*40;uint bits=U(p+4);transitions.Add(new{Index=i,ID=U(p),Bits=bits,EndType=bits&15,Interpolation=(bits>>4)&15,Curve=(bits>>8)&15,ExitFrame=F(p+8),StartFrame=F(p+16),BlendFrames=F(p+20),ContinueLayer=H(p+32),ContinueMask=H(p+34)});}var maps=new List<object>();for(int i=0;i<U(56);i++)maps.Add(new{ID=U(mp+i*8),Index=U(mp+i*8+4)});return new{Kind="fsm",Transitions=transitions,Maps=maps,TreeOffset=L(16),Graph=new DeepAudit(b,root+L(16)).Graph()};}
public static void Write(string input,string output){var obj=Parse(input);Directory.CreateDirectory(Path.GetDirectoryName(output));File.WriteAllText(output,JsonSerializer.Serialize(obj,new JsonSerializerOptions{WriteIndented=true}));}
public static void SaveNames(string output)=>File.WriteAllText(output,JsonSerializer.Serialize(BoneNames,new JsonSerializerOptions{WriteIndented=true}));
}



